9	// requireError 断言 err 是 *Error 且 Kind 匹配。
10	func requireError(t *testing.T, err error, kind ErrorKind) *Error {
11		t.Helper()
12		if err == nil {
13			t.Fatalf("期望错误 %s，实际为 nil", kind)
14		}
15		var se *Error
16		if !errors.As(err, &se) {
17			t.Fatalf("期望 *Error，实际为 %T: %v", err, err)
18		}
19		if se.Kind != kind {
20			t.Fatalf("期望错误 %s，实际为 %s（%v）", kind, se.Kind, err)
21		}
22		return se
23	}
